sys_variable_value.value:
(function execute(inputs, outputs) {
	try {

        var sysId = inputs.current_value;
        var rs_ritm = new GlideRecord('sc_req_item');
		rs_ritm.addQuery('sys_id',sysId);
		rs_ritm.query();
		var ritm = null;
		if (rs_ritm.next()) {
			ritm = rs_ritm;
		}


		var flow_inputs = {};
		flow_inputs['table_name'] = 'sc_req_item';
		flow_inputs['request_item'] = ritm; // GlideRecord of table: sc_req_item 

        
		
		
	// This variable tracks how many workflow contexts have been cancelled.
    //var cancelContext = 0;

    // Get the sys_id of the current flow context record[sys_flow_context]
    //var currentContextID = ritm.flow_context.getValue('sys_id');

       // var rs_context = new GlideRecord('sys_flow_context');
		//rs_context.addQuery('sys_id',currentContextID);
		//rs_context.query();
		//var currentContext = null;
		//if (rs_context.next()) {
		//	currentContext = rs_context;
		//}
    //cancelContext = sn_fd.FlowAPI.cancel(currentContextID, 'This flow is being cancelled because it is being restarted');

    // Get the GlideRecord for the current flow context record[sys_flow_context]
    //var currentContext = new GlideRecordUtil().getGR('sys_flow_context', currentContextID);
    

	
	

     

    // Start Asynchronously: Uncomment to run in background.
	//sn_fd.FlowAPI.getRunner().flow('x_1755490_asset_0.demo_flow').inBackground().withInputs(flow_inputs).run();


	// Execute Synchronously: Run in foreground.
	sn_fd.FlowAPI.getRunner().flow('x_1755490_asset_0.demo_flow').inForeground().withInputs(flow_inputs).run();
     //sn_fd.FlowAPI.startFlow('x_1755490_asset_0.demo_flow',flow_inputs);

//ritm.update();

	} catch (ex) {
		var message = ex.getMessage();
		gs.error(message);
	}
})(inputs, outputs);

